contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes a target address and a bool to set freeze
    function run(address target, bool freeze) public payable {
        require(target != address(0));
        // observe current owner and frozen status
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        bool beforeFrozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // attempt freezeAccount and record whether it reverted
        bool reverted;
        c.freezeAccount(target, freeze); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool afterFrozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // General property:
        // - If this contract is the owner, call must succeed (not revert) and frozenAccount[target] equals requested value.
        // - If this contract is not the owner, call must revert and frozenAccount[target] remains unchanged.
        assert(
            (address(this) == owner && reverted == false && afterFrozen == freeze)
            ||
            (address(this) != owner && reverted == true && afterFrozen == beforeFrozen)
        );
    }

    receive() external payable {}
}

