    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, bool freeze) internal {
        vm.assume(target != address(0));
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        bool beforeFrozen;
        try c.frozenAccount(target) returns (bool __r) { beforeFrozen = __r; } catch { return; }
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterFrozen;
        try c.frozenAccount(target) returns (bool __r) { afterFrozen = __r; } catch { return; }
        assertTrue((address(this) == owner && reverted == false && afterFrozen == freeze)
            ||
            (address(this) != owner && reverted == true && afterFrozen == beforeFrozen));
